    /**
     * Handles create a Tag.  if not key provided, calls create, otherwise calls save
     * @param		Tag	tag
     * @return		Tag 
     */
	@PostMapping("/create")
    public Tag create( @RequestBody(required=true) CreateTagCommand command ) {
    	Tag entity = null;
		try {       
        	
			entity = TagBusinessDelegate.getTagInstance().createTag( command );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage(), exc );        	
        }
		
		return entity;
    }

    /**
     * Handles updating a Tag.  if no key provided, calls create, otherwise calls save
     * @param		Tag tag
     * @return		Tag
     */
	@PutMapping("/update")
    public Tag update( @RequestBody(required=true) UpdateTagCommand command ) {
		Tag entity = null;
		try {                        	        
			// -----------------------------------------------
			// delegate the UpdateTagCommand
			// -----------------------------------------------
			entity = TagBusinessDelegate.getTagInstance().updateTag(command);;
	    }
	    catch( Throwable exc ) {
	    	LOGGER.log( Level.WARNING, "TagController:update() - successfully update Tag - " + exc.getMessage());        	
	    }		
		
		return entity;
	}
 
    /**
     * Handles deleting a Tag entity
     * @param		command ${class.getDeleteCommandAlias()}
     */
    @DeleteMapping("/delete")    
    public void delete( @RequestBody(required=true) DeleteTagCommand command ) {                
    	try {
        	TagBusinessDelegate delegate = TagBusinessDelegate.getTagInstance();

        	delegate.delete( command );
    		LOGGER.log( Level.WARNING, "Successfully deleted Tag with key " + command.getTagId() );
        }
        catch( Throwable exc ) {
        	LOGGER.log( Level.WARNING, exc.getMessage() );
        }

	}        
	
    /**
     * Handles loading a Tag using a UUID
     * @param		UUID uuid 
     * @return		Tag
     */    
    @GetMapping("/load")
    public Tag load( @RequestParam(required=true) UUID uuid ) {    	
    	Tag entity = null;

    	try {  
    		entity = TagBusinessDelegate.getTagInstance().getTag( new TagFetchOneSummary( uuid ) );   
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Tag using Id " + uuid );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Tag business objects
     * @return		Set<Tag>
     */
    @GetMapping("/")
    public List<Tag> loadAll() {                
    	List<Tag> tagList = null;
        
    	try {
            // load the Tag
            tagList = TagBusinessDelegate.getTagInstance().getAllTag();
            
            if ( tagList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Tags" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Tags ", exc );
        	return null;
        }

        return tagList;
                            
    }


